entries[221887] = { ["name"] = "Divine Steed", ["text"] = "Instant\nRetribution ( Retribution Paladin )\nLeap atop your Charger for 4 sec, increasing movement speed by 100%. Usable while indoors or in combat.\n\nHoly, Protection\nLeap atop your Charger for 3 sec, increasing movement speed by 100%. Usable while indoors or in combat.\n\"Only the most distinguished paladins are given the honor of riding this elekk. Its plated armor and purple adornments have been blessed by Prophet Velen himself.\"\nQuest" }
